\":[[[\"$\",\"$L20\",\"wfwundefined-0-bhaktāḥ\",{\"href\":\"/en/search/synonyms/?original=bhaktāḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"bhaktāḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"devotees\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-5\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-rāja\",{\"href\":\"/en/search/synonyms/?original=rāja\",\"children\":[\"$\",\"em\",null,{\"children\":\"rāja\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-ṛṣayaḥ\",{\"href\":\"/en/search/synonyms/?original=ṛṣayaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"ṛṣayaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"saintly kings\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-6\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tathā\",{\"href\":\"/en/search/synonyms/?original=tathā\",\"children\":[\"$\",\"em\",null,{\"children\":\"tathā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"also\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-7\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-anityam\",{\"href\":\"/en/search/synonyms/?original=anityam\",\"children\":[\"$\",\"em\",null,{\"children\":\"anityam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"temporary\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-8\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-asukham\",{\"href\":\"/en/search/synonyms/?original=asukham\",\"children\":[\"$\",\"em\",null,{\"children\":\"asukham\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"full of miseries\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-9\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-lokam\",{\"href\":\"/en/search/s